<?php defined('_JEXEC') or die; ?><div class="container-fluid"><h1>Vehicles</h1><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Registration</th><th>Type</th><th>Make/model</th><th>Condition</th><th>Operational</th><th>Compliance</th></tr></thead><tbody><?php foreach($this->items as $item): ?><tr><td><?php echo htmlspecialchars($item['registration_number'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($item['type_title']??'',ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars(trim($item['make'].' '.$item['model']),ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($item['condition_status'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($item['operational_status'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($item['compliance_status'],ENT_QUOTES,'UTF-8'); ?></td></tr><?php endforeach; ?><?php if(!$this->items): ?><tr><td colspan="6">No vehicles have been added.</td></tr><?php endif; ?></tbody></table></div></div>
